local _, ns = ...

-- Text captured in game that no other table covered, translated afterwards (build_capture_lua.py).
local exact = {
    ["(Complete)"] = "(Fuldfør)",
    ["(Dungeon)"] = "(Fangehul)",
    ["(PvP)"] = "(PvP)",
    ["(Raid)"] = "(Togt)",
    ["<Click to Engrave Rune>"] = "<Klik for at gravere rune>",
    ["<The cat yawns and regards you through heavily-lidded eyes.>"] = "<Katten gaber og betragter dig med halvtunge øjne.>",
    ["All Runes"] = "Alle Runer",
    ["Alliance Towers Controlled"] = "Alliancens Tårne Kontrolleret",
    ["Available Channels"] = "Tilgængelige Kanaler",
    ["Blood Guard Pepmeddres"] = "Blodvagt Pepmeddres",
    ["Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Gormok at Light's Hope Chapel."] = "Erobr Kronvagtens Tårn, Østmur-tårnet, Nordpas-tårnet og Pestskov-tårnet i de Østlige Pestlande, og vend derefter tilbage til Udsending Gormok ved Lysets Håb-kapellet.",
    ["Click this button to clean up your bags.|n|nIt auto-sorts and moves items out of the way to make room for new items."] = "Klik på denne knap for at rydde op i dine tasker.|n|nDen sorterer automatisk og flytter genstande af vejen for at gøre plads til nye genstande.",
    ["Collapse options |A:editmode-up-arrow:16:11:0:3|a"] = "Sammenfold indstillinger |A:editmode-up-arrow:16:11:0:3|a",
    ["Damage:"] = "Skade:",
    ["Defense:"] = "Forsvar:",
    ["Deliver the Call to Arms Announcement to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands."] = "Lever Kald til Våben-kundgørelsen til Protokolvogteren ved Lysets Håb-kapellet i de Østlige Pestlande.",
    ["Enter Naxxramas and uncover the Fate of Ramaladni."] = "Skriv Naxxrammas ind og afdæk Ramaladdis Skæbne.",
    ["Filler Text"] = "Fyldtekst",
    ["Greetings, Pepmeddres. I am Duke Nicholas Zverenhoff of the Argent Dawn."] = "Hilsner, Pepmeddres. Jeg er Hertug Nikolaj Dyrehoff fra Sølvdæmringen.",
    ["Hej, druid. Undskyld mig, jeg har en samtale i gang med Rumlat. Han mener, at selv dette land ikke er uden for redning. "] = "Hej, druid. Undskyld mig, jeg har en samtale i gang med Rumlat. Han mener, at selv dette land ikke er uden for redning. ",
    ["Hello, Rayne. What brings the Cenarion Circle to the Plaguelands?"] = "Hej, Regn. Hvad fører Cenarion-kredsen til Pestlandene?",
    ["Hello, druid. Please excuse me as I am having a conversation with Rimblat. He believes that even this land is not beyond saving."] = "Hej, druide. Undskyld mig, jeg fører en samtale med Rumlat. Han mener, at selv dette land ikke er uden for redning.",
    ["Horde Territory"] = "Hordens Territorium",
    ["Horde Towers Controlled"] = "Hordens Tårne Kontrolleret",
    ["I would like to buy from you."] = "Jeg vil gerne købe hos dig.",
    ["I'm far too busy to be playing 'guess the smell' with you, tauren. State your business or get out of my sight!"] = "Jeg er alt for travl til at lege 'gæt lugten' med dig, tyrefolket. Sig, hvad du vil, eller forsvind mig af syne!",
    ["I'm what you call a capitalist, tauren."] = "Jeg er, hvad man kalder en kapitalist, tyrefolket.",
    ["Idol"] = "Idol",
    ["Invasion"] = "Invasion",
    ["Item Name"] = "Genstandsnavn",
    ["Level level race class"] = "Niveau niveau race klasse",
    ["Master craftsman Omarion just vanished one night. Like a toot in the wind... Poof! Gone! Bah, now I'm the only one left to craft the goods for the boys on the front lines. "] = "Mester-håndværker Omarjon forsvandt bare én nat. Som en prut i vinden... Puf! Væk! Bah, nu er jeg den eneste tilbage til at fremstille varerne til drengene på frontlinjen. ",
    ["Pepmeddres"] = "Pepmeddres",
    ["Power:"] = "Kraft:",
    ["PvP"] = "PvP",
    ["Pyntegenstand"] = "Pyntegenstand",
    ["Quest Title"] = "Questtitel",
    ["Rayne, where should I look for savage fronds?"] = "Regn, hvor skal jeg lede efter vilde bregnblade?",
    ["Services"] = "Tjenester",
    ["Show me your wares, Wilhelm."] = "Vis mig dine varer, Vilhelm.",
    ["The Argent Dawn placed the call for aid, and you, among others, have answered. There is no time for us to provide you with training. Our faith is placed in your abilities, and that you will join us in throwing back this Scourge threat."] = "Sølvdæmringen har sendt opfordringen om hjælp, og du er blandt dem, der har svaret. Der er ingen tid til at give dig træning. Vores tro er sat på dine evner, og at du vil slutte dig til os i at slå denne Svøben-trussel tilbage.",
    ["The Scourge have returned in greater numbers than we have seen before. The Argent Dawn is recruiting all willing and capable men and women to defend our lands.\n\nIf we share common cause, take this document to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands."] = "Svøben er vendt tilbage i større antal, end vi nogensinde har set. Sølvdæmringen hverver alle villige og dygtige mænd og kvinder til at forsvare vores lande.\n\nHvis vi deler en fælles sag, så tag dette dokument med til Protokolvogteren ved Lysets Håb-kapellet i Østlige Pestlande.",
    ["Vapenkjortel"] = "Våbenkjortel",
    ["Venture to Alterac Valley, located in the Alterac Mountains. Find and speak with Warmaster Laggrond - who stands outside the tunnel entrance - to begin your career as a soldier of Frostwolf. You will find Alterac Valley north of Tarren Mill at the base of the Alterac Mountains."] = "Begiv dig til Alterac-dalen, beliggende i Alterac-bjergene. Find og tal med Krigsmester Laggrønd - som står uden for tunnelindgangen - for at begynde din karriere som soldat i Frostulv. Du finder Alterac-dalen nord for Tarrenmølle ved foden af Alterac-bjergene.",
    ["Very well - your deeds have been entered into the records, and you are duly recognized for your efforts.  Keep up the good work, druid.\n\nIf you have any more signets to hand in, then I am able to assist you further in that regard."] = "Meget godt - dine bedrifter er blevet indført i protokollen, og du er behørigt anerkendt for din indsats.  Bliv ved med det gode arbejde, druide.\n\nHvis du har flere seglringe at aflevere, kan jeg hjælpe dig yderligere i den sag.",
    ["You earned this, scrub. Now, don't cry about your orders. Fill 'em or destroy 'em.\r\n"] = "Du fortjente det her, din lille nisse. Nu skal du ikke hyle over dine ordrer. Fyld dem ud eller ødelæg dem.\r\n",
    ["You know the drill, kid. One valor token gets you a craftsman's writ."] = "Du kender proceduren, unge. Ét modmærke giver dig Håndværkerens Brev.",
    ["You've come to join our order, have you not?"] = "Du er kommet for at slutte dig til vores orden, ikke sandt?",
    ["startrink"] = "stjernedrik",
    ["Ah! Wonderful. The wolf meat should do nicely. Oh, don't worry, Dinmor, I wouldn't forget my part of the bargain. Here, one of these should fit you."] = "Ah! Vidunderligt. Ulvekødet burde gøre det fint. Åh, bekymr dig ikke, Dinmor, jeg ville ikke glemme min del af handlen. Her, en af disse burde passe dig.",
    ["Ah, well aren't you a sturdy-looking one? Perhaps you can assist me with a thing or two. Not much help around here except for green apprentices, and they've other things to worry about."] = "Ah, nå, er du ikke en robust en at se på? Måske kan du assistere mig med et par ting. Der er ikke meget hjælp at hente her, undtagen grønne lærlinge, og de har andre ting at bekymre sig om.",
    ["Competing in the Battlegrounds!"] = "Deltagelse i Slagmarkerne!",
    ["Deliver the stack of letters to Talin Keeneye."] = "Lever bunken af breve til Talin Skarpøje.",
    ["Hm, I don't suppose you'd be willing to do a favor for me, lad? A stack of letters came through the pass today, but I don't have the time to send them along.\n\nThey're all addressed to Talin Keeneye. You can find him to the west down the road. He's set up camp next to the frozen lake.\n\nWhat do you say?"] = "Hm, du har vel ikke lyst til at gøre mig en tjeneste, knægt? En bunke breve kom gennem passet i dag, men jeg har ikke tid til at sende dem videre.\n\nDe er alle adresseret til Talin Skarpøje. Du finder ham mod vest, nede ad vejen. Han har slået lejr ved den frosne sø.\n\nHvad siger du?",
    ["Paladin"] = "Paladin",
    ["Read the Glyphic Memorandum and speak to Marryk Nurribit inside Anvilmar above Coldridge Valley."] = "Læs Glyfisk Memorandum og tal med Gifte Nurribit inde i Ambolmar oven for Kuldekam-dalen.",
    ["Tenacious little buggers, aren't they?"] = "Seje små krabater, ikke?",
    ["While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the mage trainer Marryk. Take a gander at it and go find him inside Anvilmar when you've a chance."] = "Mens du hjalp mig, blev dette memorandum givet til mig, så jeg kunne videregive det til dig. Tag dig lidt tid til at læse det, når du får chancen. Jeg tror, det kom fra magiker-træneren Gifte. Kig på det og find ham inde i Ambolmar, når du har chancen.",
    ["Wolves giving you a bit of trouble? You'd do well to avoid the fangs and claws and other sharp bits, yes?"] = "Ulve giver dig lidt besvær? Du gør klogt i at undgå hugtænderne, klørne og de andre skarpe stykker, ja?",
    ["|TInterface\\DialogFrame\\UI-Dialog-Icon-AlertNew:16:16:0:0:64:64:0:64:0:64|t Dethrone|r"] = "|TInterface\\DialogFrame\\UI-Dialog-Icon-AlertNew:16:16:0:0:64:64:0:64:0:64|t Afsæt|r",
    ["  (PvP)"] = "  (SmS)",
    ["Apparently"] = "Tilsyneladende",
    ["If the problems we've had here are indicative of what is happening elsewhere in our lands, by Magni's beard, we have some troubles ahead of us! I can only hope that the king and Senate are taking steps to deal with the threat the troggs pose."] = "Hvis de problemer, vi har haft her, er et tegn på, hvad der sker andre steder i vores lande, så af Magnies skæg, har vi nogle problemer forude! Jeg kan kun håbe, at kongen og Senatet tager skridt til at tackle den trussel, trogerne udgør.",
    ["Ah good, now this will hit the spot.  Allow me to take a small break while I enjoy this scalding mornbrew!"] = "Ah godt, nu rammer det plet.  Lad mig tage en lille pause, mens jeg nyder denne Skoldhed Morgenbrygg!",
    ["Ahh, excellent. It's been a while since I received word from Ironforge."] = "Ahh, fremragende. Der er gået et stykke tid, siden jeg sidst fik bud fra Jernsmede.",
    ["Alliance Territory"] = "Alliancens Territorium",
    ["Aye, I'm Durnan Furcutter.  You have something for me?"] = "Jep, jeg er Durnan Pelsskærer.  Har du noget til mig?",
    ["Bring Felix's Box, Felix's Chest and Felix's Bucket of Bolts to Felix Whindlebolt in Anvilmar."] = "Bring Felix' Kasse, Felix' Bryst og Felix' Spand med Skruer til Felix Vindbolt i Ambolmar.",
    ["Deliver the letter to Grelin Whitebeard."] = "Lever brevet til Grelin Hvidskæg.",
    ["Excellent! I can go back to my... leisurely... hunting now. Thank you, Dinmor."] = "Fremragende! Nu kan jeg vende tilbage til min... afslappede... jagt. Tak, Dinmor.",
    ["Greetings, lad. I'm Grelin Whitebeard. I'm here to examine the threat posed by the growing numbers of trolls in Coldridge Valley. What have I found? It's a bit troubling..."] = "Hilsner, knægt. Jeg er Grelin Hvidskæg. Jeg er her for at undersøge truslen fra de voksende mængder af troll i Kuldekam-dalen. Hvad har jeg fundet? Det er lidt bekymrende...",
    ["Greetings, mage! Fine day for hunting, wouldn't you say? I've been having more than a little luck with boars, myself. Perhaps you'd like a shot?"] = "Hilsner, magiker! Fin dag til jagt, ville du ikke sige? Jeg har selv haft mere end lidt held med vildsvin. Måske vil du have et skud?",
    ["Greetings.  I'm a gnome mage trainer, and you're a mage."] = "Hilsner.  Jeg er en gnom-magikertræner, og du er en magiker.",
    ["Hello, mage!  Ready for some training?"] = "Hej, magiker!  Klar til noget træning?",
    ["I am interested in mage training."] = "Jeg er interesseret i magikertræning.",
    ["I sell the finest cloth and leather garb this side of the valley!"] = "Jeg sælger de fineste klæde- og læderdragter på denne side af dalen!",
    ["If I remember correctly, Grelin's camp is down the road to the southeast. No doubt he'll be eager to get his mail."] = "Hvis jeg husker rigtigt, ligger Grelins lejr nede ad vejen mod sydøst. Uden tvivl er han ivrig efter at få sin post.",
    ["Is there something I can help you with?"] = "Kan jeg være til hjælp med noget?",
    ["Now that hit the spot!  Nothing like a piping hot - nay, SCALDING mornbrew on a cold winter's day to warm your cackles of yer soul.\n\nHere ya go Dinmor - be a pal and take this empty mug back to Nori for me, would ya now."] = "Nu ramte det plet!  Intet slår en pibende varm - nej, SKOLDENDE morgenbryg på en kold vinterdag for at varme dine sjælekagler.\n\nVær så god, Dinmor - vær en ven og tag det tomme krus med tilbage til Nori for mig, vil du nu.",
    ["Oh, yeah! Arcane Arts... of course.\n\nHere's what you need to know, Dinmor: Don't get into too much trouble. Save some coin to buy me an ale... or any spells ya might want. And stay the heck away from Gnomeregan. Other than that, have a good day! I'll be here if you need me or want to train... or whatever."] = "Åh, jo! Arkan Kunst... selvfølgelig.\n\nHer er det, du skal vide, Dinmor: Undlad at komme i for meget ballade. Spar nogle mønter til at købe en øl til mig... eller enhver besværgelse, du måtte ønske dig. Og hold dig for pokker væk fra Gnomregan. Ellers: hav en god dag! Jeg er her, hvis du har brug for mig eller vil træne... eller hvad som helst.",
    ["Return Nori's Mug to Nori Pridedrift."] = "Returnér Noris Krus til Nori Stolthed.",
    ["Take a Scalding Mornbrew to Durnan Furcutter inside Anvilmar before it gets cold in five minutes!"] = "Tag en Skoldhed Morgenbrygg til Durnan Pelsskærer inde i Ambolmar, før den bliver kold om fem minutter!",
    ["Thank you, I've been waiting for these letters for quite some time...\n\nUnfortunately, these letters aren't all for me. This one is addressed to Grelin Whitebeard. He's not too far away if you'd like to deliver it to him."] = "Tak, jeg har ventet på disse breve i ganske lang tid...\n\nDesværre er brevene ikke alle til mig. Dette er adresseret til Grelin Hvidskæg. Han er ikke alt for langt væk, hvis du vil levere det til ham.",
    ["Yeah, what's that, gnome? Speak up, if you don't mind. I don't hear so good after a few ales."] = "Jo, hvad siger du, gnom? Tal højere, hvis du ikke har noget imod det. Jeg hører ikke så godt efter et par øl.",
    ["Yes? Do you have something for me?"] = "Ja? Har du noget til mig?",
    ["Upon periodic perusal of the nether, we came across the following reagents.  Good day, and... please be more careful when dealing with the arcane."] = "Ved periodisk gennemgang af tomrummet stødte vi på følgende reagenser.  God dag, og... vær venligst mere forsigtig når I omgås det arkane.",
    ["Argh! Those Light-blasted trolls!\n\n<He takes a few breaths and seems to settle down... a bit.>\n\nA group of them came in the night and stole my journal! I knew better than to trust that good-for-nothing appr..."] = "Av! De lysblæste trolde!\n\n<Han tager et par vejrtrækninger og virker til at falde lidt til ro... lidt.>\n\nEn flok af dem kom om natten og stjal min dagbog! Jeg burde have vidst bedre end at stole på den til-ingenting-duelige lærling...",
    ["Dungeon difficulty set to Normal"] = "Fangehulets sværhedsgrad sat til Normal",
    ["Escape the effects of any immobilization or movement speed reduction effect."] = "Undslip virkningerne af enhver immobilisering eller reduktion af bevægelseshastighed.",
    ["Excellent, Dinmor!  You'd be surprised how many couriers I meet who forget to do something as simple as bring back the mug.  Mugs don't grow on trees, or so they tell me!\n\nHere's a little something for the effort.  Thanks again for your help."] = "Fremragende, Dinmor! Du ville blive overrasket over hvor mange budbringere jeg møder, der glemmer at gøre noget så simpelt som at bringe krusen tilbage. Krus gror jo ikke på træer, siger de i hvert fald!\n\nHer er lidt for besværet. Tak igen for din hjælp.",
    ["Grelin Whitebeard wants you to kill Grik'nir the Cold, and retrieve his journal."] = "Grelin Hvidskæg vil have dig til at dræbe Grik'nir den Kolde og hente hans dagbog.",
    ["I trust the scalding mornbrew got to Durnan on time!  Did you remember to bring me back my mug?"] = "Jeg stoler på at den brændende morgenbryg nåede Durnan til tiden! Huskede du at tage min krus med tilbage?",
    ["My journal! They took it away to the cave. The one that had it... It was a big brute with some odd markings on his skin and face. I didn't get a much better look than that.\n\nYou've had some luck with the trolls, maybe you could go get it back for me?"] = "Min dagbog! De tog den med til hulen. Ham der havde den... Det var en stor brølende kæmpe med nogle underlige mærker på hud og ansigt. Jeg fik ikke et meget bedre kig end det.\n\nDu har haft lidt held med trolde, måske kunne du gå og hente den tilbage til mig?",
    ["Greetings.  I'm a mage trainer, and you're a mage."] = "Hilsner.  Jeg er en magiker-træner, og du er en magiker.",
    ["Quandary"] = "Dilemma",
    ["The Light protect you, mage."] = "Lyset beskytter dig, magiker.",
    ["All Subclasses"] = "Alle underklasser",
    ["Can I teach you how to turn the meat you find on beasts into a feast?"] = "Kan jeg lære dig at gøre det kød, du finder på bæsterne, om til et gilde?",
    ["Fill yer tankard and pull up a chair. We've stories to tell and kegs to empty."] = "Fyld din krus og træk en stol op. Vi har historier at fortælle og tønder at tømme.",
    ["Here, let me show you how to bind those wounds...."] = "Her, lad mig vise dig, hvordan du binder de sår....",
    ["I can teach you how to cook!"] = "Jeg kan lære dig at lave mad!",
    ["I can train you in First Aid techniques."] = "Jeg kan træne dig i førstehjælpsteknikker.",
    ["Train me."] = "Træn mig.",
    ["What can I do at an inn?"] = "Hvad kan jeg gøre på en kro?",
    ["Bring Samuel Fipps' Rester til Marlas Grav, og vend derefter tilbage til Novice Elret."] = "Bring Samuel Fipsens Rester til Marlas Grav, og vend derefter tilbage til Nybegynder Elret.",
    ["Hello, rogue!  Ready for some training?"] = "Hej, skurk!  Klar til lidt træning?",
    ["I would like to train."] = "Jeg vil gerne træne.",
    ["No other race on Azeroth has suffered as much as our people, rogue. To laugh in the face of death has become second nature for all of us."] = "Ingen andre race på Azerot har lidt så meget som vores folk, skurk. At le døden lige i øjnene er blevet sekundnatur for os alle.",
    ["SHIFT-T"] = "SKIFT-T",
    ["With the sanction of Lord Varimathras, the Deathstalkers' numbers grow. More blades to strike at our enemies when they least expect it."] = "Med Herre Varimatras' billigelse vokser Dødsstalkernes tal. Flere klinger, der kan give fjenderne stød, når de mindst venter det.",
    ["(Hold Shift)"] = "(Hold Skift)",
    ["Deliver the Sealed Letter to Glix Xizzix in the Undercity."] = "Aflever det Forseglet Brev til Glix Klikklak i Undergrunden.",
    ["Find Yvette Farthing, and deliver to her the letter from Thurman Agamand."] = "Find Ivette Fjerding, og aflever brevet fra Thurmann Agamand til hende.",
    ["Oi, what do you want?"] = "Hov, hvad vil du have?",
    ["Reagenser: |nSoul Shard"] = "Reagenser: |nSjælskår",
    ["Take Apothecary Johaan's findings to Apothecary Renferrel in Silverpine Forest."] = "Bring Apoteker Johans fund til Apoteker Renferrel i Sølvfyrreskoven.",
    ["Your bags are full."] = "Dine tasker er fulde.",
    ["Your class cannot use Bows"] = "Din klasse kan ikke bruge Buer",
    ["Your class cannot use Leather"] = "Din klasse kan ikke bruge Læder",
    ["Your class cannot use Mail"] = "Din klasse kan ikke bruge Ringbrynje",
    ["Your class cannot use One-Handed Maces"] = "Din klasse kan ikke bruge Enhånds-Køller",
    ["Your class cannot use Two-Handed Maces"] = "Din klasse kan ikke bruge Tohånds-Køller",
    ["Abandon \"The Family Crypt\"?"] = "Opgiv \"Familiekrypten\"?",
    ["Ah, one of our own. It is good to see our numbers are growing so rapidly that I can no longer keep track of the faces of our members.\n\nThat fool Thrall thinks I am working hard to cleanse the image of warlocks and prove we are his servants. Idiot! The Burning Legion will make ash of this entire world after it drains it completely."] = "Ah, en af vores egne. Det er godt at se, at vores tal vokser så hurtigt, at jeg ikke længere kan holde styr på medlemmernes ansigter.\n\nDen fjols Trael tror, jeg arbejder hårdt på at rense hekseriets image og bevise, at vi er hans tjenere. Idiot! Den Brændende Legion vil gøre hele denne verden til aske, når den har drænet den fuldstændigt.",
    ["Arcane:"] = "Arkan:",
    ["As the Dark Lady wills."] = "Som Den Mørke Dame ønsker.",
    ["Bring Migi's Lunch to him behind Grommash Hold."] = "Bring Mumles Frokost til ham bag Grommash-borgen.",
    ["Bring a Lieutenant's Insignia from the Burning Blade in Skull Rock to Thrall."] = "Bring en Løjtnantens Insignia fra Brændende Klinge i Kranieklippen til Trael.",
    ["Bring a Lieutenant's Insignia to Thrall in Orgrimmar."] = "Bring en Løjtnantens Insignia til Trael i Orgrimgrad.",
    ["Bring the Book of Ur from Shadowfang Keep to Keeper Bel'dugur."] = "Bring Bog om Ær fra Skyggehugger-fæstningen til Vogter Bel'dugur.",
    ["Bring the Nether Gem to Bethor Iceshard in the Undercity."] = "Bring Nether-ædelstenen til Bethor Isskår i Undergrunden.",
    ["Critical Strike:"] = "Kritisk Slag:",
    ["Deliver the Abominable Head to the Undercity."] = "Lever Afskyeligt Hoved til Undergrunden.",
    ["Find Deathstalker Adamant and Deathstalker Vincent inside Shadowfang Keep."] = "Find Dødsstalker Stålhård og Dødsstalker Vinsent inde i Skyggehugger-fæstningen.",
    ["Find Maur Grimtotem's corpse inside Ragefire Chasm and search it for anything of interest."] = "Find Maur Gribetotems lig inde i Vredesild-kløften og søg det for noget interessant.",
    ["Fire:"] = "Ild:",
    ["Frost:"] = "Frost:",
    ["Give Yelmak's Potion to Whuut."] = "Giv Yelmaks Eliksir til Vuut.",
    ["Greetings, traveler."] = "Hilsner, rejsende.",
    ["Hmm..."] = "Hmm...",
    ["I have the finest meats in Orgrimmar."] = "Jeg har de fineste bøffer i Orgrimgrad.",
    ["I thank you for the motivation."] = "Jeg takker dig for motivationen.",
    ["I wish to unlearn my class or legacy talents."] = "Jeg ønsker at glemme mine klasse- eller arvetalenter.",
    ["Main Hand:"] = "Hovedhånd:",
    ["Mana Regen:"] = "Mana-genopretning:",
    ["May I have another?"] = "Må jeg få en til?",
    ["Movement Speed:"] = "Bevægelseshastighed:",
    ["Now that the crystal is here..."] = "Nu hvor krystallen er her...",
    ["Place Clarice's Pendant on Yuriv's Tomb in Silverpine."] = "Placér Clarices Vedhæng på Yurivs Grav i Sølvfyr.",
    ["Put the spirit of Faldrim Anvilmar to rest."] = "Læg Faldrim Ambolmars ånd til hvile.",
    ["Ranged:"] = "Distance:",
    ["Return Gunther's Spellbook to him, on the island of Gunther's Retreat."] = "Returner Gunners Besværgelsesbog til ham, på øen Gunners Tilbagetog.",
    ["Slay Taragaman the Hungerer and recover Taragaman the Hungerer's Heart."] = "Dræb Taragaman den Sultne og gendan Taragaman den Sultnes Hjerte.",
    ["Speak with Magistrate Sevren in Brill."] = "Tal med Dommer Sevrin i Gryde-by.",
    ["Speak with Seereth Stonebreak in the Stonetalon Mountains."] = "Tal med Seereth Stenbrud i Stenklippe-bjergene.",
    ["Take the Grimtotem Satchel to Rahauro in Thunder Bluff."] = "Tag Grimtotem-tasken til Rahaurø i Tordenklippe.",
    ["There is no escape, even in death."] = "Der er ingen flugt, selv ikke i døden.",
    ["Visit Borstan's Firepit and tell him Thatog wants you to deliver Migi's lunch to him personally."] = "Besøg Brændstans Bålsted og fortæl ham, at Tykmave vil have dig til at levere Mumles frokost til ham personligt.",
    ["We SMASH IT WITH A HAMMER!"] = "VI SMADRER DEN MED EN HAMMER!",
    ["Wham!"] = "Bam!",
    ["Why should I pace myself if this is working?"] = "Hvorfor skulle jeg tage det roligt, hvis det her virker?",
    ["Yes!"] = "Ja!",
    ["Your class cannot use Guns"] = "Din klasse kan ikke bruge Geværer",
    ["and return to Kor'geld in Yelmak's Alchemy and Potions."] = "og vend tilbage til Kor'guld i Yelmaks Alkymi og Eliksirer.",
    ["deliver Migi's lunch to him personally."] = "lever Mumles frokost til ham personligt.",
    ["then bring his heart back to Neeru Fireblade in Orgrimmar."] = "så bring hans hjerte tilbage til Neeru Ildklinge i Orgrimgrad.",
    ["Access the control console at the Venture Company research site."] = "Få adgang til kontrolkonsollen på Ventureselskabets forskningssted.",
    ["Blizzard services are currently unavailable.|n|nYour Real ID and BattleTag friends will not show up. You will also not be able to send or receive new Real ID or BattleTag friend requests. A game restart may be required to re-enable functionality."] = "Snestorm-tjenester er midlertidigt utilgængelige.|n|nDine Ægte ID- og KampTag-venner vil ikke dukke op. Du vil heller ikke kunne sende eller modtage nye venneanmodninger via Ægte ID eller KampTag. Et spilgenstart kan være nødvendigt for at genaktivere funktionaliteten.",
    ["Bring the Secure Crate to Wharfmaster Dizzywig in Ratchet."] = "Bring Sikret Kasse til Havnemester Svimlig i Skralde.",
    ["Brug: Teaches you how to craft Brawler's Leather Armor."] = "Brug: Lærer dig at fremstille Slagsbrors Læderrustning.",
    ["Brug: Teaches you how to craft Totemic Leather Armor."] = "Brug: Lærer dig at fremstille Totemist Læderrustning.",
    ["Collect the Highly Toxic Strain from Witherfang."] = "Saml den Yderst Giftige Stamme fra Visnetand.",
    ["Enchanting: Enchant Bracer - Minor Deflect"] = "Fortryllings: Fortrylling Armbeskytter - Mindre Afbøjning",
    ["Explore the waters of the Forgotten Pools"] = "Udforsk vandene i De Glemte Pøle",
    ["Find Mankrik's wife and then return to him in the Crossroads."] = "Find Mankriks kone og vend så tilbage til ham ved Korsvejen.",
    ["Hit Chance:"] = "Træffersikkerhed:",
    ["I came to the Crossroads from the south seeking help, warlock, but I find only cowards who turn their backs on me--even the mighty Thork insults me so. He is a good leader, but his dismissal of my plea causes me greater anger.\n\nHe claims my rage makes me hasty--that it clouds my judgement--but I will not rest until I have vengeance!"] = "Jeg kom til Korsvejen fra syd for at søge hjælp, hekser, men jeg finder kun kujoner, der vender ryggen til mig--selv den mægtige Tork fornærmer mig sådan. Han er en god leder, men hans afvisning af min anmodning gør min vrede endnu større.\n\nHan påstår, at mit raseri gør mig forhastet--at det tager dømmekraften fra mig--men jeg vil ikke hvile, før jeg har hævn!",
    ["I would like to talk about something else."] = "Jeg vil gerne tale om noget andet.",
    ["Investigate the disappearance of Edward Heartweaver in Ruins of Lordaeron."] = "Undersøg forsvinden af Edward Hjertevæver i Ruinerne af Herrelande.",
    ["Item level:"] = "Genstandsniveau:",
    ["Nature:"] = "Natur:",
    ["Pattern: Brawler's Leather Armor"] = "Mønster: Slagsbrors Læderrustning",
    ["Pattern: Totemic Leather Armor"] = "Mønster: Totemist Læderrustning",
    ["Reagenser: |nLesser Magic Essence"] = "Reagenser: |nMindre Magi-essens",
    ["Roll Need!"] = "Rul Behov!",
    ["Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest."] = "Søg Vredesild-kløften efter Maur Gribetotems lig og undersøg det for eventuelle interessante genstande.",
    ["Shadow:"] = "Skygge:",
    ["Speak to Neeru Fireblade in Orgrimmar."] = "Tal med Neeru Ildklinge i Orgrimgrad.",
    ["Speak to Thrall in Orgrimmar and tell him what you've learned."] = "Tal med Trael i Orgrimgrad og fortæl ham, hvad du har lært.",
    ["Speak with Tonga Runetotem at the Crossroads."] = "Tal med Tonja Runetotem ved Korsvejen.",
    ["Spell Damage:"] = "Besværgelsesskade:",
    ["Spell Healing:"] = "Besværgelsesheling:",
    ["The enchanted flame resonates within you. Campfire effects gained while affected have increased duration."] = "Den fortryllede flamme genlyder i dig. Lejrbålseffekter opnået, mens du er påvirket, har øget varighed.",
    ["Turn in your sealed crates and the Shipping Label here"] = "Aflever dine forseglede kasser og Forsendelsesetiketten her",
    ["We've had trouble with shipments going missing across Azeroth. If you find any, I'd appreciate if you could return them to me."] = "Vi har haft problemer med forsendelser, der forsvinder rundt om i Azerot. Hvis du finder nogen, vil jeg sætte pris på, om du kunne returnere dem til mig.",
    ["Well met, warlock. You may speak to me unless you have direct business with my mistress Magatha.\n\nI deal with most of her tasks for her so she can concentrate on more important matters. Perhaps there are some things we could discuss before you seek audience with her?"] = "Velkommen, hekser. Du må gerne tale med mig, medmindre du har direkte ærinde hos min frue Magata.\n\nJeg klarer de fleste af hendes opgaver for hende, så hun kan koncentrere sig om vigtigere sager. Måske er der nogle ting, vi kunne drøfte, før du søger audiens hos hende?",
    ["What are Craftsman's Writs?"] = "Hvad er Håndværkerens Breve?",
    ["What are Waylaid Supply Crates?"] = "Hvad er Forsvundne Forsyningskasser?",
    ["Will you help me find my dog?"] = "Vil du hjælpe mig med at finde min hund?",
    ["Yes yes yes!  You're just the undead I'm looking for!\n\nSit!  We have much to discuss!!"] = "Ja ja ja!  Du er lige den udøde, jeg leder efter!\n\nSid!  Vi har meget at drøfte!!",
    ["<Othmar's head looks at you from nearby.>\r\n\r\nWhat... You... Want...\r\n\r\nFilthy... undead..."] = "<Oddmars hoved stirrer på dig fra nærliggende.>\r\n\r\nHvad... Du... Vil...\r\n\r\nSnavsede... udøde...",
    ["<The body looks incomplete and appears to be awaiting a head.>"] = "<Kroppen ser ufuldstændig ud og ser ud til at vente på et hoved.>",
    ["Bring the Crest of Lordaeron to Oran Snakewrithe in Undercity."] = "Bring Herrelandenes Våbenskjold til Orla Slangevrid i Undergrunden.",
    ["Deliver the Abominable Head to Master Apothecary Faranell within the Undercity."] = "Lever Afskyeligt Hoved til Mesterapoteker Faranell inden for Undergrunden.",
    ["Do not presume to speak to me as though you are my equal, warlock. Sylvanas is my queen, and I will do as she bids.\n\nIf you do not show the proper respect, I assure you, we can find a more than suitable place for you in the Nether.\n\nBut there is no reason we cannot have words if you wish to aid the Dark Lady..."] = "Anmaß dig ikke at tale til mig, som om du er min ligemand, hekser. Silvanas er min dronning, og jeg vil gøre, som hun befaler.\n\nHvis du ikke viser den rette respekt, kan jeg forsikre dig om, at vi kan finde et mere end passende sted til dig i Nether.\n\nMen der er ingen grund til, at vi ikke kan have en snak, hvis du ønsker at bistå Den Mørke Dame...",
    ["Investigate the disappearance of Edward Heartweaver in the Ruins of Lordaeron."] = "Undersøg forsvindingen af Edward Hjertevæver i Ruinerne af Herrelande.",
    ["Return to your corpse"] = "Retur til dit lig",
    ["The liquids and mixtures all bubble and spasm as you approach. Next to the equipment lies a large pair of tongs that look as though they would be adequate for dropping in samples of ooze.\n\nThere is safety gear present, but it appears to be dusty and well-ignored.\n\nYou don't think touching anything would be wise."] = "Væskerne og blandingerne bobler og krampetrækker, når du nærmer dig. Ved siden af udstyret ligger et stort par tang, som ser ud til at være passende til at dumpe prøver af slimvæsen i.\n\nDer er sikkerhedsudstyr til stede, men det ser ud til at være støvet og godt ignoreret.\n\nDu tror ikke, at det ville være klogt at røre ved noget.",
    ["This is not the first time I have had to reprimand you! The electrical pulses of this heart are much too strong. This new heart has seared almost all of the flesh and ligaments of this construct!"] = "Dette er ikke første gang, jeg har måttet irettesætte dig! Hjertets elektriske impulser er alt for stærke. Dette nye hjerte har brændt næsten alt kødet og alle ledbåndene i denne konstruktion!",
    ["UUUUUuuuuurrrgh!!"] = "ÅÅÅÅÅuuuuurrrgh!!",
    ["Abandon \"Miner's Fortune\"?"] = "Opgiv \"Minearbejderens Lykke\"?",
    ["Ah, good.  These spores have rendered nicely.  Thank you, Raiju."] = "Ah, godt.  Disse sporer er blevet pænt udtørret.  Tak, Raiju.",
    ["BLOOD AND BOOOOONES! CHOL'ARUK HUNGERS!"] = "BLOD OG KNOOOOOGLER! CHOL'ARUK SULTER!",
    ["Blood and bones!"] = "Blod og knogler!",
    ["Cavern of Mists"] = "Tågehulen",
    ["Cavern of Mists, The Wailing Caverns"] = "Tågehulen, Jammergrotterne",
    ["Chol'aruk will feast!"] = "Chol'aruk vil holde fest!",
    ["Chol'aruk!"] = "Chol'aruk!",
    ["Few have the ambition to seek true power. Fewer still have the resolve to do what is necessary to claim it. Power belongs to those who are willing to pay its price, warlock."] = "Få har ambitionen til at søge sand kraft. Endnu færre har viljen til at gøre det nødvendige for at tage den. Kraft tilhører dem, der er villige til at betale prisen, hekser.",
    ["Gained the following camp benefits:\nGained the following camp benefits:"] = "Opnåede følgende lejrfordele:\nOpnåede følgende lejrfordele:",
    ["If you find him, or if you find... anything, then please let me know."] = "Hvis du finder ham, eller hvis du finder... noget som helst, så lad mig det vide.",
    ["Praise to the Banshee Queen, it isn't often I have visitors out here."] = "Pris til Banshee-dronningen, det er ikke tit, jeg får besøg herude.",
    ["Thank you for the spores, Mamoco.  They are now prepared for transport."] = "Tak for sporerne, Mamoco.  De er nu klargjort til transport.",
    ["The Barrens is no place for the weak, or the long-winded.  I won't waste your time with unneeded words.\n\nI expect the same from you."] = "Ødemarken er ikke noget sted for de svage eller de langsommelige.  Jeg spilder ikke din tid med unødvendige ord.\n\nJeg forventer det samme af dig.",
    ["The Ravener will consume the world!"] = "Ådseleren vil opsluge verden!",
    ["There.  I am finished with your robe, Gaby."] = "Der.  Jeg er færdig med din kåbe, Gaby.",
    ["Unread mail from:\nUnread mail from:"] = "Ulæst post fra:\nUlæst post fra:",
    ["WANTED: Baron Longshore\nWANTED: Baron Longshore"] = "EFTERLYST: Baron Langkyst\nEFTERLYST: Baron Langkyst",
    ["You are fluent in the following languages:\r\n|cffffffffOrcish|r\r\n|cffffffffGutterspeak|r"] = "Du taler flydende følgende sprog:\r\n|cffffffffOrcisk|r\r\n|cffffffffGadesprog|r",
    ["\"The last remnant of the ancient elemental defender of a Highborne city.\""] = "\"Den sidste rest af den gamle elementar-forsvarer i en Højfødte by.\"",
    ["(Summon)"] = "(Fremkald)",
    ["Abandon \"Deviate Hides\", destroying Deviate Hide?"] = "Opgiv \"Afviger-skind\", og ødelæg Afviger-skindet?",
    ["Abandon \"Stolen Silver\"?"] = "Opgiv \"Stjålet Sølv\"?",
    ["Aku'mai's Lair"] = "Aku'Mais Hule",
    ["Aku'mai's Lair, Blackfathom Deeps"] = "Aku'Mais Hule, Den Sorte Afgrund",
    ["And this is Corma Villard. Two weeks married, her wife was spirited away from the safety of Menethil Harbor."] = "Og dette er Corma Vildmand. To uger gift, og hendes kone blev revet væk fra sikkerheden i Menetil-havnen.",
    ["Be on your guard, |cff00ff00Sut|r!"] = "Vær på din vagt, |cff00ff00Sut|r!",
    ["Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity."] = "Bring Bogen om Ær til Vogter Bel'dugur ved Apotekerium i Undergrunden.",
    ["Bring the Damp Note to Je'neu Sancrea in Ashenvale."] = "Bring den Fugtige Seddel til Je'neu Sancrea i Askedalen.",
    ["Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."] = "Bring den Mærkelige Vandkugle til Je'neu Sancrea ved Zoram'gar-forposten, Askedalen.",
    ["Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.\n\n|cff6e5c40Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.|r"] = "Bring den Mærkelige Vandkugle til Je'neu Sancrea ved Zoram'gar-forposten, Askedalen.\n\n|cff6e5c40Bring den Mærkelige Vandkugle til Je'neu Sancrea ved Zoram'gar-forposten, Askedalen.|r",
    ["Brug: Attempt to cleanse the globe."] = "Brug: Forsøg at rense kuglen.",
    ["Brug: Teaches you how to craft Acolyte's Chain Shirt."] = "Brug: Lærer dig at fremstille Akolyttens Kædeskjorte.",
    ["Defeat Lorgus Jett in Blackfathom Deeps."] = "Besejr Lorgus Jett i Den Sorte Afgrund.",
    ["Defeat Twilight Lord Kelris and recover the Head of Kelris."] = "Besejr Tusmørkeherre Kelris og genvind Kelriss Hoved.",
    ["Dusting off a messenger bag emerging from the soil, you find a parchment nestled among the supplies."] = "Du tørrer støv af en budbringer-taske, der stikker op af jorden, og finder et pergament gemt blandt forsyningerne.",
    ["Ehh? You look a little too new to be doing business with me.\r\n\r\nCome back once you're a bit more familiar with how they do things around here. Trust me."] = "Øh? Du ser lidt for grøn ud til at handle med mig.\r\n\r\nKom tilbage, når du er lidt mere fortrolig med, hvordan de gør tingene her omkring. Stol på mig.",
    ["Find the Deathstalker Adamant and Deathstalker Vincent."] = "Find Dødsstalker Stålhård og Dødsstalker Vinsent.",
    ["Five and five years, and she still searches for her, though she was no beauty, and there were many ladies that would take her place."] = "Fem og fem år, og hun leder stadig efter hende, selvom hun ikke var nogen skønhed, og der var mange damer, der ville tage hendes plads.",
    ["I'd like to talk about something else."] = "Jeg vil gerne tale om noget andet.",
    ["If you want to know about the comings and goings of caravans and merchants here in Splintertree Post, then I am fortunately the orc you are looking for.  Unfortunately for you though, I don't like people.\n\nIf you want something, make it quick."] = "Hvis du vil vide noget om kommen og gåen af karavaner og købmænd her i Splintertræ-Posten, så er jeg heldigvis den ork, du leder efter.  Desværre for dig kan jeg ikke lide folk.\n\nHvis du vil have noget, så gør det hurtigt.",
    ["Interesting, interesting... I know of a druid that lives atop the hill above the Wailing Caverns, Sut. She might be able to tell you more about this shard you have found.\n\nNow, I must get back to work!"] = "Interessant, interessant... Jeg kender til en druide, der bor oppe på bakken over Jammergrotterne, Sut. Hun kan måske fortælle dig mere om denne skår, du har fundet.\n\nNu må jeg tilbage til arbejdet!",
    ["May I have the globe I brought you? I believe it can help me with something relating to the highborne in the area."] = "Maj jeg få kuglen, jeg bragte dig? Jeg tror, den kan hjælpe mig med noget vedrørende de Højfødte i området.",
    ["Moonshrine Ruins"] = "Månehelligdoms-ruinerne",
    ["Moonshrine Ruins, Blackfathom Deeps"] = "Månehelligdoms-ruinerne, Den Sorte Afgrund",
    ["Moonshrine Sanctum, Blackfathom Deeps"] = "Månehelligdommen, Den Sorte Afgrund",
    ["Plans: Acolyte's Chain Shirt"] = "Tegninger: Akolyttens Kædeskjorte",
    ["Quest Item Sapphire of Aku'Mai might be needed for the quest The Essence of Aku'Mai. \n\nAre you sure you want to delete this?"] = "Opgavegenstanden Safir af Aku'Mai kan være nødvendig for opgaven Essensen af Aku'Mai. \n\nEr du sikker på, at du vil slette denne?",
    ["Recover the Fathom Core from the Fathom Stone in Blackfathom Deeps."] = "Genvind Dybkernen fra Favnstenen i Den Sorte Afgrund.",
    ["Recover the Lorgalis Manuscript from Blackfathom Deeps."] = "Genvind Lorgalis-manuskriptet fra Den Sorte Afgrund.",
    ["Return a Filled Etched Phial to Zangen Stonehoof in Thunder Bluff."] = "Tag en Fyldt Ætset Fiol retur til Zangen Stenhov i Tordenklippe.",
    ["Scout the gazebo on Mystral Lake that overlooks the nearby Alliance outpost."] = "Spejd lysthuset ved Mystral-søen, der kigger ud over den nærliggende Alliance-forpost.",
    ["So be it. I only ask that you share any findings with me that may help with our research into the Twilight's Hammer.\r\n\r\nElements be with you, warlock."] = "Så være det. Jeg beder kun om, at du deler alle fund med mig, der kan hjælpe med vores forskning i Tusmørkets Hammer.\r\n\r\nElementerne være med dig, hekser.",
    ["The Drowned Sacellum"] = "Det Druknede Sacellum",
    ["The Drowned Sacellum, Blackfathom Deeps"] = "Det Druknede Sacellum, Den Sorte Afgrund",
    ["The Forgotten Pool, Blackfathom Deeps"] = "Den Glemte Pøl, Den Sorte Afgrund",
    ["The Kirin Tor did not heed my warnings! The Alliance is a sham. Arugal is a reckless fool."] = "Kirin Tårn lyttede ikke til mine advarsler! Alliancen er en bluff. Arugal er en hensynsløs tåbe.",
    ["The Pool of Ask'ar"] = "Ask'ars Pyt",
    ["The Pool of Ask'ar, Blackfathom Deeps"] = "Ask'ars Pyt, Den Sorte Afgrund",
    ["This is my own private domicile, and I will not be harassed... *!@#$!"] = "Dette er mit eget private hjem, og jeg vil ikke chikaneres... *!@#$!",
    ["This is the brazier, |cff00ff00Sut|r. Put it out. Vorsha is a beast, worthy of praise from no one!"] = "Dette er bækkenet, |cff00ff00Sut|r. Slå det ud. Vorsha er et udyr, værdigt ros fra ingen!",
    ["This will be a tough fight, Grumpy. Follow me closely!"] = "Det bliver en hård kamp, Grumpy. Følg mig tæt!",
    ["This will be a tough fight, Mo. Follow me closely!"] = "Det bliver en hård kamp, Mo. Følg mig tæt!",
    ["Water spray dampens the air, the view is incredible."] = "Vandspray dæmper luften, udsigten er ufattelig.",
    ["Yeah, %^&*!! Magnets!"] = "Ja, %^&*!! Magneter!",
    ["You have my deepest gratitude, |cff00ff00Sut|r. I thank you."] = "Du har min dybeste taknemmelighed, |cff00ff00Sut|r. Jeg takker dig.",
    ["\n|cFFFFB2D0On a crate, just inside the ogre tower at Gallows' Corner."] = "\n|cFFFFB2D0Ovenpå en kasse, lige inden for ogertårnet ved Galgehjørnet.",
    ["\"Elixir of Wisdom\""] = "\"Visdomseliksir\"",
    ["A Bit of Wet Work"] = "Lidt af Vådt Arbejds",
    ["A Little Payback"] = "En Lille Gengæld",
    ["Berserker Shackles"] = "Berserker-lænker",
    ["Bloodslash Axe"] = "Blodhugs-økse",
    ["Bring Ambassador Malcin's Head to Varimathras in the Undercity."] = "Bring Ambassadør Malsins Hoved til Varimatras i Undergrunden.",
    ["Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity."] = "Bring Kenaffa, Fardøl og Marcel Dabyris' Hoveder til Genavie Grønskolling i Undergrunden.",
    ["Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff."] = "Bring Rasorflankes Hjerte til Gamle Stenspir i Tordenklippe.",
    ["Bring Robes of the Arcana to Menara Voidrender in the Barrens."] = "Før Kapper af Arkana til Menara Tomrumsrivet i Ødemarken.",
    ["Bring Sharptalon's Claw to Senani Thunderheart at Splintertree Post, Ashenvale."] = "Før Skarpklos Klo til Senani Torduhjerte ved Splintertræ-Posten, Askedalen.",
    ["Bring Ursangous's Paw to Senani Thunderheart at Splintertree Post, Ashenvale."] = "Før Bjørnegus' Pote til Senani Torduhjerte ved Splintertræ-Posten, Askedalen.",
    ["Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."] = "Før Forurenet Vandkugle til Je'neu Helligkrea ved Zoram'gar-forposten, Askedalen.",
    ["Bring the Befouled Water Globe to Mastok Wrilehiss at Splintertree Post, Ashenvale."] = "Før Forurenet Vandkugle til Mastok Snirkelsnor ved Splintertræ-Posten, Askedalen.",
    ["Bring the Titan Relic to Muln Earthfury at the Skywatcher Plateau in northwest Mulgore."] = "Før Titan-relikvien til Muln Jordvrede ved Himmelvagtens Plateau i det nordvestlige Mulgorr.",
    ["Bring the barrier down."] = "Før barrieren ned.",
    ["Bring the letter you recovered from Broodmother Valraxx to Muln Earthfury at Skywatcher Plateau."] = "Før brevet du hentede fra Yngelmoder Valraxx til Muln Jordvrede ved Himmelvagtens Plateau.",
    ["Bring word of Varian Wrynn's fate to Thrall in Orgrimmar."] = "Før nyt om Varian Skævsens skæbne til Trael i Orgrimgrad.",
    ["Brug: Teaches you how to craft Defender's Leather Helm."] = "Brug: Lærer dig at fremstille Forsvarerens Læderhjelm.",
    ["Brug: Teaches you how to craft Guard's Chain Helm."] = "Brug: Lærer dig at fremstille Vagtens Kædehjelm.",
    ["Burn Away"] = "Forbrænding Væk",
    ["Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill."] = "Saml Arkan-partikel i Dalarns By til Magus Ordeen Tomglimt i Tarrenmølle.",
    ["Confrontation"] = "Konfrontation",
    ["Courier's Clasp"] = "Kurerens Spænde",
    ["Cracked. Cracked. CRACKED.\r\n\r\nI can't make use of any of these! I said disable the sentries, not obliterate them! How dangerous could they have been?\r\n\r\nMy dreams of magus abominations are at a standstill. For now."] = "Revnet. Revnet. REVNET.\r\n\r\nJeg kan ikke bruge nogen af disse! Jeg sagde, at vagterne skulle deaktiveres, ikke udslettes! Hvor farlige kunne de dog have været?\r\n\r\nMine drømme om magus-abominationer står stille. For nu.",
    ["Deathstalker Masoj needs you to place the three Apothecary Vials on peaks around Hillsbrad Foothills and return to him."] = "Dødsstalker Masoj har brug for, at du placerer de tre Apotekerglas på toppene rundt om Hillsbrad-forbjergene og vender tilbage til ham.",
    ["Defeat Atrexis the Grave Knight in the Dalaran Underbelly."] = "Besejr Atrexis Gravridderen i Dalarns Underlivet.",
    ["Deliver Belgrom's Sealed Note to Moktar Krin in Thousand Needles."] = "Lever Belgroms Forseglede Seddel til Moktar Krinsen i Tusindnåle.",
    ["Deliver Korran's Sealed Note to Belgrom Rockmaul in Orgrimmar."] = "Lever Korrands Forseglede Seddel til Belgrom Klippeknokler i Orgrimgrad.",
    ["Deliver the Filled Etched Phial to Rau Cliffrunner at the Freewind Post."] = "Lever Fyldt Ætset Fiol til Rau Klippeløber ved Frihvind-posten.",
    ["Excellent work. That beast is unworthy to walk among the dead. Let him lie beneath them."] = "Fremragende arbejde. Det udyr er ikke værdigt til at gå blandt de døde. Lad ham ligge under dem.",
    ["Fatebound Buckler"] = "Skæbnebundet Rundskjold",
    ["Find Strahad Farsan in Ratchet."] = "Find Strahad Farsøn i Skralde.",
    ["Find the four Forsaken traitors at the Lordamere Internment Camp, recover their Bloodstone artifacts, and return to Magus Wordeen Voidglare."] = "Find de fire forrædere fra De Forladte ved Lordamere-interneringslejren, genvind deres Blodsten-artefakter og vend tilbage til Magus Ordeen Tomglimt.",
    ["Forged in Fire"] = "Smedet i Ild",
    ["Good work. We advance the plans.\r\n\r\nDeathstalkers dare.\r\n\r\nLet purpose guide your strikes, Sut."] = "God gerning. Vi fremskynder planerne.\r\n\r\nDødsstalkere tør.\r\n\r\nLad formålet vejlede dine slag, Sut.",
    ["Grips of Control"] = "Greb af Kontrol",
    ["Honor is gained by killing members of the opposite faction in PvP combat. You can use honor points to purchase special items."] = "Ære opnås ved at dræbe medlemmer af den modsatte fraktion i SmS-kamp. Du kan bruge ærespegs til at købe særlige genstande.",
    ["How do you do, fellow Dalaranian? Sure is a lotta ruckus today, eh?"] = "Hvordan går det, medDalaraner? Der er sandelig en masse ballade i dag, hva'?",
    ["I am Muln Earthfury of the Earthen Ring. What brings you before me today?"] = "Jeg er Muln Jordvrede fra Jordringen. Hvad fører dig frem for mig i dag?",
    ["I guess I shouldn't have sent a stooge to look for priceless artifacts. This is barely worth sellin' at a tourist kiosk! What, did you just grab the first book that seemed to be jutting out from the rest?\r\n\r\nForget it. Maybe I can spray it with gold and say it belonged to an arch mage or somethin'."] = "Jeg gætter på, at jeg nok ikke skulle have sendt en håndlanger ud for at lede efter uvurderlige artefakter. Den her er knap nok værd at sælge i en turistkiosk! Hvad, tog du bare den første bog, der stak ud fra de andre?\r\n\r\nGlem det. Måske kan jeg sprøjte guld på den og sige, at den tilhørte en ærkemagiker eller noget.",
    ["Incarnadine Blade"] = "Blodrød Klinge",
    ["Kar Aman, Sut. You look to be a strong warlock--you would do well to mind yourself in this area. Touching things you know nothing about, or showing disrespect to your elders is just cause for punishment.\n\nYou may not respect me or my companions, but you will learn to respect our power if you prove foolish enough.\n\nNow, enough with the pleasantries, was there something I can do for you?"] = "Kar Amanen, Sutte. Du ser ud til at være en stærk hekser--du vil gøre brønd i at passe godt på dig selv i dette område. At røre ved ting du intet aner om, eller vise respektløshed over for dine ældre, er en ren grund til straf.\n\nDu respekterer måske hverken mig eller mine følgesvende, men du vil lære at respektere vores kraft, hvis du er dum nok til at bevise det.\n\nNu, nok med høfligheder--var der noget jeg kan gøre for dig?",
    ["Kernobee Rescue"] = "Kernobi-redning",
    ["More Valuable Than Gold"] = "Mere Værdifuld End Guld",
    ["No Quarter"] = "Ingen Kvart",
    ["Oathbound Bracers"] = "Edsbundne Armbeskyttere",
    ["Oh my, a shade of the archmage? How utterly embarrassing for them.\r\n\r\nAnd the Kirin Tor allowed you into their inner chambers? Interesting. This could provide an opportunity..."] = "Åh du milde, en skygge af ærkemageren? Hvor fuldstændig pinligt for dem.\r\n\r\nOg Kirin Tårn lod dig komme ind i deres indre kamre? Interessant. Det her kunne måske give en mulighed...",
    ["Oh, you are back."] = "Åh, du er tilbage.",
    ["Oily Grippers"] = "Oliet Gribere",
    ["Path of Renewal"] = "Fornyelsens Vej",
    ["Pattern: Defender's Leather Helm"] = "Mønster: Forsvarerens Læderhjelm",
    ["Place Karang's Banner on the Foulweald Totem Mound.  Do not let the furbolgs destroy the banner.  Defeat Chief Murgut and bring Murgut's Totem to Karang Amakkar at Zoram'gar."] = "Placér Kæmpens Banner på Rådskov-totemhøjen.  Lad ikke pelsbjørnene ødelægge banneret.  Nederlag Høvding Murgøt og bring Murguts Totem til Karang Hammerstrøm ved Zoram'gård.",
    ["Plans: Guard's Chain Helm"] = "Tegninger: Vagtens Kædehjelm",
    ["Recover Zarla's Journal from the depths of Alcaz Prison."] = "Genvind Zarlås Dagbog fra dybderne af Alcaz-fængslet.",
    ["Retrieve the Moldy Tome and Tattered Manuscript for Jorah Annison in the Undercity."] = "Hent den muggne tomo og det frynsede manuskript til Jorah Årsen i Undergrunden.",
    ["Return Vorrel Sengutz's wedding ring (from Nancy Vishas) to Monika Sengutz in Tarren Mill."] = "Retur Vorrel Sengudsens bryllupsring (fra Nanna Vishas) til Monika Sengudsen i Tarrenmølle.",
    ["Slay Alliance soldiers encroaching into the Barrens at the border to Dustwallow Marsh, then return to Grunt Logmar at Camp Taurajo."] = "Slå Alliance-soldater ihjel, der trænger ind i Ødemarken ved grænsen til Støvsumpen, og vend derefter tilbage til Grunt Tømmerstok ved Taurajo-lejren.",
    ["Slay Stormheart in Thousand Needles and acquire its heart."] = "Slå Stormhjerte ihjel i Tusindnåle og skaf dig dets hjerte.",
    ["Somber News"] = "Dystre Nyheder",
    ["Speak to Menara Voidrender in the Barrens."] = "Tal med Menara Tomrumsrivet i Ødemarken.",
    ["Speak to Takata Steelblade in Desolace."] = "Tal med Takata Stålklinge i Ørkenløs.",
    ["Speak with Felgur Twocuts at Ghost Walker Post in Desolace."] = "Tal med Felgur Tvehugg ved Spøgelsesvandrer-posten i Ørkenløs.",
    ["Speak with Jorah Annison in the Undercity."] = "Tal med Jorah Årsen i Undergrunden.",
    ["Speak with Regthar Deathgate."] = "Tal med Regthar Dødsporten.",
    ["Speak with Scooty in Booty Bay."] = "Tal med Skuti i Bytteviken.",
    ["Speak with the Image of Archmage Modera near Dalaran."] = "Tal med Billedet af Ærkemager Modera nær Dalarn.",
    ["Tailoring: Azure Silk Pants"] = "Skrædderi: Azurblå Silkebukser",
    ["Tailoring: Green Woolen Vest"] = "Skrædderi: Grøn Uldvest",
    ["Tailoring: Heavy Woolen Gloves"] = "Skrædderi: Tunge Uldhandsker",
    ["Tailoring: Lesser Wizard's Robe"] = "Skrædderi: Mindre Troldmandskappe",
    ["Tailoring: Pearl-clasped Cloak"] = "Skrædderi: Perlespændt Kappe",
    ["Take Darthalia's Sealed Commendation to Varimathras in the Undercity."] = "Tag Mørkthalias forseglede Anbefaling til Varimatras i Undergrunden.",
    ["Take the Mudsnout Composite to Master Apothecary Faranell in the Undercity."] = "Tag Mudderblomst-kompositten til Mesterapoteker Faranell i Undergrunden.",
    ["Take the Small Scroll to Varimathras in the Undercity."] = "Tag den Lille Rulle til Varimatras i Undergrunden.",
    ["The dust of the Barrens parches my throat more and more every day, SUT. But it is worth the sacrifice to remain here if it helps the Horde and the warchief."] = "Ødemarkens støv tørrer min hals mere og mere for hvert eneste døgn, SUT. Men det er værd at ofre sig ved at blive her, hvis det hjælper Horden og krigshøvdingen.",
    ["The ebb and flow of magic has been disrupted, of late. I hear that even the mages of Dalaran are perplexed. Is this disturbance arcane in nature, or are the elements themselves in unrest?"] = "Magiens ebbe og flod er blevet forstyrret på det seneste. Jeg hører, at selv magikerne i Dalarn er forundrede. Er denne forstyrrelse arkan af natur, eller er elementerne selv i uro?",
    ["The value in these cores is that they are powerful. The downside is that means the constructs are powerful. Good luck."] = "Værdien i disse kerner er, at de er kraftfulde. Ulempen er, at det betyder, at konstruktionerne er kraftfulde. Held og lykke.",
    ["This quest is completed in the area OUTSIDE Razorfen Downs."] = "Denne opgave fuldføres i området UDENFOR Rasorhegn-hederne.",
    ["Thrall Needs to Know"] = "Trael Skal Vide Det",
    ["Thrall of Duty"] = "Trael af Pligt",
    ["Wait for Scooty to calibrate the Goblin Transponder."] = "Vent på at Skuti kalibrerer Nisse-transponderen.",
    ["We shen'dorei have need of additional cloth to replenish our supplies. Any donations you make would be put to good use, and surely raise your esteem with the Windshapers."] = "Vi stjernebørn har brug for ekstra klæde for at fylde vores lager op. Alle donationer I giver ville blive brugt godt, og det vil helt sikkert hæve jeres anseelse hos Vindformerne.",
    ["We're here to clean up your mess. Grant us access to the archmage's chambers so we may put an end to this."] = "Vi er her for at rydde op i jeres rod. Giv os adgang til ærkemagikerens kamre, så vi kan gøre ende på det her.",
    ["Well? Didja find their library? There's gotta be somethin' good in there."] = "Nå? Fandt I deres bibliotek? Der må da være noget godt derinde.",
    ["What'ya need from ol' Mazu'kon, warlock?"] = "Hvad vil du have fra gamle Mazu'konnen, hekser?",
    ["Would you like me to remove the barrier?"] = "Skal jeg fjerne barrieren?",
    ["Wrex's Pinky Ring"] = "Vrækses Lillefinger-ring",
    ["You came. I'll admit, I'm surprised."] = "I kom. Jeg må indrømme, at jeg er overrasket.",
    ["You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band."] = "Du må enten beholde ringen, eller du må finde den person, der står bag prægningen og indgraveringerne på indersiden af ringen.",
    ["You were right to come straight back to me. Have you found anything in Dalaran?"] = "Du gjorde klogt i at komme lige tilbage til mig. Har du fundet noget i Dalarn?",
    ["|cFFffffffPlace Karang's Banner on the Foulweald Totem Mound. Do not let the furbolgs destroy the banner. Defeat Chief Murgut and bring Murgut's Totem to Karang Amakkar at Zoram'gar.|r"] = "|cFFffffffPlacér Kæmpens banner på Rådskov-totemhøjen. Lad ikke pelsbjørnene ødelægge banneret. Giv Høvding Murgøt et Nederlag, og bring Murguts Totem til Karang Hammerstrøm ved Zoram'gård.|r",
    ["A Tale Spun Around the Fire"] = "En Fortælling Spundne Rundt om Ilden",
    ["A Token of Vengeance"] = "Et Mærke af Hævn",
    ["Ah, one of my favorite customers. You look to be of a warlock of some power, Sut. I am pleased to meet you. If there is anything I can do for you, please, just ask.\n\nMy brother and I feel that it will be your kind who lead us into the next great era. One with such power... such control... it's only a matter of time before the Legion itself bends to your will.\n\nI am but a little envious."] = "Ah, en af mine yndlingskunder. Du ser ud til at være en hekser af en vis kraft, Sutte. Jeg er glad for at møde dig. Hvis der er noget, jeg kan gøre for dig, så spørg bare.\n\nMin bror og jeg har en fornemmelse af, at det er din slags, der vil føre os ind i den næste store æra. En med så stor kraft... så stor kontrol... det er kun et spørgsmål om tid, før selveste Legion bøjer sig for din vilje.\n\nJeg er dog lidt misundelig.",
    ["Answer Parqual Fintallas' question successfully and then speak to him again."] = "Besvar Parqual Finttallas' spørgsmål korrekt, og tal derefter med ham igen.",
    ["Bigger Rock on Bigger Stick"] = "Større Sten på Større Stok",
    ["Breakfast at Booty Bay"] = "Morgenmad i Bytteviken",
    ["Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles."] = "Bring Rok'Alims Fragmenter til Dorn Slettejæger i Tusindnåle.",
    ["Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles."] = "Bring Grenkas Klo til Dorn Slettejæger i Tusindnåle.",
    ["Bring Roon's Kodo Horn to Hemet Nesingwary in Stranglethorn."] = "Bring Roons Kodo-horn til Hemmet Jagtvarys i Kvælertorn.",
    ["Bring Steelsnap's Rib to Melor Stonehoof in Thunder Bluff."] = "Bring Stålbids Ribben til Melor Stenhov i Tordenklippe.",
    ["Bring an Oracle Crystal to Maurin Bonesplitter in Desolace."] = "Bring et Orakelkrystal til Maurin Knoglekløver i Ørkenløs.",
    ["Bring the Maraudine Key Fragment to Umarak in the Desolace."] = "Bring Plyndrer-nøglefragmentet til Umarok i Ørkenløs.",
    ["Deliver Cliffwatcher Longhorn Report to Nataka Longhorn at Ghost Walker Post in Desolace."] = "Lever Klippevagt Langhorn-rapporten til Natakka Langhorn ved Spøgelsesvandrer-posten i Ørkenløs.",
    ["Deliver the Lost Shipping Crate to Friz Frazzlespark at Powderfuse Port in the Riverglades."] = "Lever den tabte forsendelseskasse til Friz Knitrespark ved Krudtlunte Portvin i Flodlunde.",
    ["Don't worry, this'll be quick! There's a path down the hill right here. I just need you to keep the path clear."] = "Undlad at bekymre dig, det går hurtigt! Der er en sti ned ad bakken lige her. Jeg skal bare have dig til at holde stien fri.",
    ["Eh? Ya have business with Nimboya?"] = "Hæ? Ka' du have ærinde med Nimboya?",
    ["Enchanting: Enchant Bracer - Lesser Intellect"] = "Fortryllings: Fortryl Armbeskytter - Mindre Intellekt",
    ["Enchanting: Enchant Chest - Intellect"] = "Fortryllings: Fortryl Bryst - Intellekt",
    ["Enchanting: Enchant Chest - Lesser Absorption"] = "Fortryllings: Fortryl Bryst - Mindre Absorbering",
    ["Enchanting: Enchant Chest - Minor Stats"] = "Fortryllings: Fortryl Bryst - Mindre Egenskaber",
    ["Enchanting: Enchant Chest - Stamina"] = "Fortrylling: Fortryl bryst - Udholdenhed",
    ["Enchanting: Enchant Cloak - Lesser Fire Resistance"] = "Fortrylling: Fortryl kappe - Mindre Ildmodstand",
    ["Enchanting: Enchant Shield - Lesser Spirit"] = "Fortrylling: Fortryl skjold - Mindre Ånd",
    ["Enchanting: Enchant Weapon - Crusader"] = "Fortrylling: Fortryl våben - Korsfarer",
    ["Enchanting: Enchant Weapon - Lesser Striking"] = "Fortrylling: Fortryl våben - Mindre Slagkraft",
    ["Enchanting: Enchant Weapon - Revelation"] = "Fortrylling: Fortryl våben - Openbaring",
    ["Enchanting: Runed Golden Rod"] = "Fortrylling: Runemærket Gylden Stang",
    ["Escort Zimmix Sputterspark to safety"] = "Eskortér Zimmiks Sprutgnist i sikkerhed",
    ["Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains."] = "Find Braug Dunsånd nær indgangen til Klodsdybe-stien i Stenklippe-bjergene.",
    ["Find Parqual Fintallas in Undercity."] = "Find Parqual Finttallas i Undergrunden.",
    ["Find The Beginnings of the Undead Threat and return it to Parqual Fintallas in Undercity.\n\nThe book is inside Scarlet Monastery: Library."] = "Find Begyndelsen til Den Udøde Trussel og returnér den til Parqual Finttallas i Undergrunden.\n\nBogen er inde i Det Skarlagenrøde Kloster: Bibliotek.",
    ["Find one of the Desolace marauders."] = "Find en af Ørkenløs' plyndrere.",
    ["First drink's on me! The coin to pay for it, that is. On my hand. From you."] = "Første drik er på mig! Mønten til at betale for den, altså. På min hånd. Fra dig.",
    ["Grom'Gol's safety is my highest priority."] = "Grum'Gols sikkerhed er min højeste prioritet.",
    ["How about we go around instead? This place isn't THAT big."] = "Hvad med at vi går udenom i stedet? Dette sted er ikke DET store.",
    ["I am done inspecting the skulls, The, and I am relieved.  Yenniku is not among them..."] = "Jeg er forvoldt med at inspicere kraniernes, Den, og jeg er lettet.  Yennikou er ikke blandt dem...",
    ["I could use some help here!"] = "Jeg kunne godt bruge noget hjælp her!",
    ["I thought you were supposed to be the one protecting me!"] = "Jeg troede, du skulle være den, der skulle beskytte mig!",
    ["If you have faith, leap from the planks overlooking Thousand Needles."] = "Hvis du har tro, så hop fra plankerne med udsigt over Tusindnåle.",
    ["Infiltrate Krol'dok Stronghold and return to Krom'rosh with proof of their leader's demise."] = "Infiltrér Krol'dok Stærkefæste og vend tilbage til Krom'rose med bevis for deres leders undergang.",
    ["Is that the key?\r\n\r\n<Zimmix lunges forward against the front of the cage and he repeatedly attempts to swipe the key from your possession.>\r\n\r\nJust hand it over!"] = "Er det nøglen?\r\n\r\n<Zimmiks udfalder forpost mod foran af buret, og han forsøger gentagne gange at snuppe nøglen fra din besiddelse.>\r\n\r\nBare overdrag den!",
    ["Listen, I like you and all, but you standing around here is making us look suspicious! If you don't have the key then, I dunno, GO GET IT!\r\n\r\nPlease?"] = "Hør nu, jeg kan godt lide dig og alt det der, men at du står og hænger rundt her får os til at se mistænksomme ud! Har du ikke nøglen, så, øh, jeg ved ikke, GÅ OG HENT DEN!\r\n\r\nVær venlig?",
    ["Locate the hunters' camp"] = "Find jægernes lejr",
    ["Looting |cff1eff00Robe of Doan|r will bind it to you."] = "Plyndring af |cff1eff00Kjole af Dån|r binder den til dig.",
    ["Maintain your reputation with the Gelkis, and bring a Draenethyst Shard to Uthek the Wise in the Gelkis Village in Desolace."] = "Oprethold din ry hos Gellekis, og bring et Draenetyst-skår til Uthek den Vise i Gellekis-landsbyen i Ørkenløs.",
    ["Place the grim message."] = "Placér det dystre budskab.",
    ["Report to Krom'rosh at the Rog'mar outpost in the Riverglades."] = "Rapportér til Krom'rose ved Rygmar-forposten i Flodlunde.",
    ["Report to Melisara at Tarren Mill in the Hillsbrad Foothills."] = "Rapportér til Melisøra ved Tarrenmølle i Hillsbrad-forbjergene.",
    ["Retrieve Helcular's Rod from the Yeti and bring it back to Novice Thaivand in Tarren Mill."] = "Hent Helkulars Stav fra Yetien og bring den tilbage til Nybegynder Taivand i Tarrenmølle.",
    ["Retrieve the Compendium of the Fallen from the Monastery and return to Sage Truthseeker in Thunder Bluff."] = "Hent De Faldnes Kompendium fra Klosteret og returner til Vismand Sandhedssøger i Tordenklippe.",
    ["Return to Menara Voidrender in the Barrens."] = "Returner til Menara Tomrumsrivet i Ødemarken.",
    ["Rusted Troll War Belt"] = "Rusten Troll-krigsbælte",
    ["Sheesh, look at the tusks on this one!"] = "Pyha, se lige hovertænderne på den her!",
    ["Show me what you have for sale."] = "Vis mig, hvad du har til salg.",
    ["Speak to Keldran in Orgrimmar."] = "Tal med Keldrun i Orgrimgrad.",
    ["Speak with Hemet Nesingwary."] = "Tal med Hemmet Jagtvarys.",
    ["Spears."] = "Spyd.",
    ["Tailoring: Mooncloth Reagent Bag"] = "Skrædderi: Månestof Reagens-taske",
    ["Take the tablet etchings to Master Gadrin in Sen'jin Village in Durotar."] = "Tag tavleindskrifterne til Mester Gadrin i Sen'jin-landsbyen i Durdotar.",
    ["Thanks to your donations, the library is thriving.\r\n\r\nPlease, take this."] = "Tak til dine donationer, blomstrer biblioteket.\r\n\r\nVær så venlig, tag denne.",
    ["The Only Good Brinescale..."] = "Den Kun Gode Saltskæl...",
    ["Travel to Hammerfall in the Arathi Highlands and speak with Zengu."] = "Rejs til Hammerfald i Arathi-højlandet og tal med Zangu.",
    ["Trouble. That's what it was. Heh... sorry."] = "Problemer. Det var hvad det var. Hehe... undskyld.",
    ["We will have to start over, once more. At least we might be able to salvage that giant electrical heart for the next abomination."] = "Vi bliver nødt til at starte forfra, endnu en gang. Men vi kan i det mindste redde det kæmpestore elektriske hjerte til den næste abekabale.",
    ["What can these old bones do for you, warlock? Perhaps you would like to hear of a troll legend?"] = "Hvad kan disse gamle knogler gøre for dig, hekser? Måske har du lyst til at høre en trold-legende?",
    ["Where's the Key?"] = "Hvor er Nøglen?",
    ["Whoa, whoa, whoa, hold on, what was that?"] = "Hov, hov, hov, hold da op, hvad var det?",
    ["Your skills are out of my league, stranger.Talk to Hgarth at the Sun Rock Retreat in the Stonetalon Mountains. He will provide you with more knowledge than I can. "] = "Dine færdigheder er uden for min liga, fremmed.Tal med Hagart ved Solklippe-tilflugtsstedet i Stenklippe-bjergene. Han vil give dig mere viden, end jeg kan. ",
    ["ssSSLIMES!! Rrraagh..."] = "ssSSLIMER!! Rrraagh...",
    ["|cFFffffff - Escort Zimmix Sputterspark to safety|r"] = "|cFFffffff - Eskortér Zimmiks Sprutgnist til sikkerhed|r",
    ["|cFFffffffEscort Zimmix Sputterspark away from the Ruins of Zul'Kunda then tell Wharfmaster Lozgil in Booty Bay of your successful rescue.|r"] = "|cFFffffffEskortér Zimmiks Sprutgnist væk fra Ruinerne af Zul'Kaffe og fortæl derefter Kajmester Lozgyl i Bytteviken om din vellykkede redning.|r",
    ["Uhh, on second thought, that cliff is pretty steep. Imagine if I slipped and broke my ankle! I couldn't ask you to carry me."] = "Øh, ved nærmere eftertanke er den klippe ret stejl. Tænk, hvis jeg gled og brækkede anklen! Jeg kunne ikke bede dig om at bære mig.",
}
local list = {
    {"^Engrave your belt with the Nourish rune%:\r\n\r\n%|T236162%:24%|t\r\nHeals a friendly target for ([%d%.,]+) to ([%d%.,]+)%. Heals for an additional ([%d%.,]+)%% if you have a Rejuvenation%, Regrowth%, Lifebloom%, or Wild Growth effect active on the target%. This spell benefits from and triggers all effects associated with Healing Touch or Regrowth%.$", "Gravér dit bælte med Nærende-runen:\r\n\r\n|T236162:24|t\r\nHeler et venligt mål for {1} til {2}. Heler for yderligere {3}%, hvis du har en Foryngelse-, Genvækst-, Livsblomst- eller Vild Vækst-effekt aktiv på målet. Denne besværgelse drager fordel af og udløser alle effekter knyttet til Helbredende Berøring eller Genvækst.", "% if you have a Rejuvenation, Regrowth, Lifebloom, or Wild Growth effect active on the target. This spell benefits from and triggers all effects associated with Healing Touch or Regrowth."},
    {"^Engrave your chest or robe with the Wild Strikes rune%:\r\n\r\n%|T132143%:24%|t\r\nWhile you are in Cat Form%, Bear Form%, or Dire Bear Form%, party or raid members within ([%d%.,]+) yards gain increased combat ferocity%.  Each melee hit has a ([%d%.,]+)%% chance of granting the attacker an extra attack with ([%d%.,]+)%% additional Attack Power%. No effect if the target is already benefitting from Windfury Totem%.\r\n$", "Gravér dit bryst eller din kåbe med Vilde Stødder-runen:\r\n\r\n|T132143:24|t\r\nMens du er i Katteform, Bjørneform eller Frygtindgydende Bjørneform, får gruppe- eller togt-medlemmer inden for {1} meter øget kampvildskab.  Hvert nærkamp-angreb har en {2}% sjans for at give angriberen et ekstra angreb med {3}% ekstra Angrebskraft. Ingen effekt, hvis målet allerede drager fordel af Vindraseri-totem.\r\n", "Engrave your chest or robe with the Wild Strikes rune:\r\n\r\n|T132143:24|t\r\nWhile you are in Cat Form, Bear Form, or Dire Bear Form, party or raid members within "},
    {"^Provides immunity to Charm%, Fear and Sleep while active%.  May also be used while already afflicted by Charm%, Fear or Sleep%.  Lasts ([%d%.,]+) sec%.$", "Giver immunitet over for Charme, Frygt og Søvn, mens den er aktiv.  Kan også bruges, mens man allerede er ramt af Charme, Frygt eller Søvn.  Varer {1} sek.", "Provides immunity to Charm, Fear and Sleep while active.  May also be used while already afflicted by Charm, Fear or Sleep.  Lasts "},
    {"^Retrieve the Rig Blueprints and Thermaplugg%'s Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar%.\r\n\n\n%|cff6e5c40([%d%.,]+)%/([%d%.,]+) Rig Blueprints%|r\n%|cff6e5c40([%d%.,]+)%/([%d%.,]+) Thermaplugg%'s Safe Combination%|r$", "Hent Rig-tegninger og Thermapluggs safekombination fra Gnomregan og bring dem til Nogg i Orgrimgrad.\r\n\n\n|cff6e5c40{1}/{2} Rig-tegninger|r\n|cff6e5c40{3}/{4} Thermapluggs safekombination|r", "Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar.\r\n\n\n|cff6e5c40"},
